-- gateway/migrations/000001_init.up.sql
-- Squashed migration: complete final schema for Nebu gateway (migrations 1–49 combined).
-- Runs as the nebu_app role. No references to nebu_migrate or legacy nebu role.
-- Generated by Story 13.14 (squash all 49 gateway migrations into a single seed migration).

-- ─── Extensions ──────────────────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ─── message_buffer ──────────────────────────────────────────────────────────
-- Message buffer for gateway resilience (ADR G12/G13)
CREATE TABLE message_buffer (
    id           BIGSERIAL PRIMARY KEY,
    txn_id       TEXT      NOT NULL,
    room_id      TEXT      NOT NULL,
    sender       TEXT      NOT NULL,
    payload      JSONB     NOT NULL,
    received_at  BIGINT    NOT NULL,
    status       TEXT      NOT NULL DEFAULT 'pending',
    retry_count  SMALLINT  NOT NULL DEFAULT 0,
    processed_at BIGINT,
    CONSTRAINT message_buffer_status_check CHECK (status IN ('pending', 'held'))
);

CREATE TABLE message_dead_letter (
    id         BIGSERIAL PRIMARY KEY,
    buffer_id  BIGINT    NOT NULL,
    txn_id     TEXT      NOT NULL,
    payload    JSONB     NOT NULL,
    failed_at  BIGINT    NOT NULL,
    last_error TEXT
);

-- ─── server_config ───────────────────────────────────────────────────────────
-- Key-value store for immutable instance configuration (ADR G8)
CREATE TABLE server_config (
    key     TEXT   PRIMARY KEY,
    value   TEXT   NOT NULL,
    set_at  BIGINT NOT NULL
);

ALTER TABLE server_config ENABLE ROW LEVEL SECURITY;
ALTER TABLE server_config FORCE ROW LEVEL SECURITY;

CREATE POLICY config_read_all ON server_config FOR SELECT USING (true);
CREATE POLICY config_insert_only ON server_config FOR INSERT WITH CHECK (true);

-- Mutable keys policy (final state from migration 000049):
-- Only these keys can be updated by nebu_app. Immutable keys (server_name,
-- bootstrap_completed, etc.) are protected at the DB level.
CREATE POLICY config_update_mutable ON server_config
    FOR UPDATE
    USING (key IN (
        'oidc_user_id_claim',
        'oidc_displayname_claim',
        'oidc_email_claim',
        'admin_group_claim',
        'oidc_issuer',
        'oidc_client_id',
        'oidc_client_secret',
        'oidc_directory_enabled',
        'oidc_directory_endpoint',
        'scim_enabled',
        'scim_base_url',
        'scim_bearer_token'
    ))
    WITH CHECK (key IN (
        'oidc_user_id_claim',
        'oidc_displayname_claim',
        'oidc_email_claim',
        'admin_group_claim',
        'oidc_issuer',
        'oidc_client_id',
        'oidc_client_secret',
        'oidc_directory_enabled',
        'oidc_directory_endpoint',
        'scim_enabled',
        'scim_base_url',
        'scim_bearer_token'
    ));

-- ─── users ───────────────────────────────────────────────────────────────────
-- Core user identity, system roles, encrypted PII, key references.
-- Final column set from migrations 4, 6, 21, 22, 34.
CREATE TABLE users (
    user_id                   TEXT    PRIMARY KEY,
    display_name_encrypted    BYTEA,
    display_name_nonce        BYTEA,
    avatar_url_encrypted      BYTEA,
    avatar_url_nonce          BYTEA,
    system_role               TEXT    NOT NULL DEFAULT 'user',
    is_active                 BOOLEAN NOT NULL DEFAULT true,
    signing_key_id            TEXT,
    encryption_key_id         TEXT,
    created_at                BIGINT  NOT NULL,
    last_seen_at              BIGINT,
    -- PII columns (migration 6)
    email_encrypted           BYTEA,
    email_nonce               BYTEA,
    email_ephemeral_pub       BYTEA,
    -- DSGVO deletion columns (migration 21)
    deletion_status           TEXT,
    keys_deleted_at           BIGINT,
    -- Anonymization column (migration 22)
    anonymized_at             BIGINT,
    -- Deactivation columns (migration 34)
    deactivated_at            BIGINT,
    deactivation_reason       TEXT,
    CONSTRAINT users_system_role_check
        CHECK (system_role IN ('user', 'instance_admin', 'compliance_officer')),
    CONSTRAINT users_deletion_status_check
        CHECK (deletion_status IN ('deletion_in_progress', 'keys_deleted'))
);

-- ─── user_keys ───────────────────────────────────────────────────────────────
CREATE TABLE user_keys (
    key_id      TEXT   PRIMARY KEY,
    user_id     TEXT   NOT NULL REFERENCES users(user_id),
    key_type    TEXT   NOT NULL,
    algorithm   TEXT   NOT NULL,
    public_key  BYTEA  NOT NULL,
    private_key BYTEA,
    created_at  BIGINT NOT NULL,
    deleted_at  BIGINT,
    CONSTRAINT user_keys_key_type_check
        CHECK (key_type IN ('signing', 'encryption'))
);

-- ─── sessions ────────────────────────────────────────────────────────────────
-- ETS + PostgreSQL hybrid since-token checkpointing for /sync recovery.
-- Final column set from migrations 5 and 30.
CREATE TABLE sessions (
    session_id          TEXT    PRIMARY KEY,
    user_id             TEXT    NOT NULL REFERENCES users(user_id),
    since_token         TEXT,
    device_id           TEXT    NOT NULL,
    last_active_at      BIGINT  NOT NULL,
    created_at          BIGINT  NOT NULL,
    -- device_display_name (migration 30)
    device_display_name TEXT
);

CREATE INDEX sessions_user_id_idx ON sessions (user_id);

