CREATE INDEX room_members_user_id_idx ON room_members (user_id);

-- ─── events ──────────────────────────────────────────────────────────────────
-- Final column set from migrations 10, 38, 43.
CREATE TABLE events (
    event_id         TEXT      PRIMARY KEY,
    room_id          TEXT      NOT NULL REFERENCES rooms(room_id),
    sender           TEXT      NOT NULL,
    event_type       TEXT      NOT NULL,
    content          JSONB     NOT NULL,
    origin_server_ts BIGINT    NOT NULL,
    signatures       JSONB,
    -- state_key (migration 38)
    state_key        TEXT,
    -- search_vector (migration 43)
    search_vector    tsvector
);

CREATE INDEX events_room_id_ts_idx ON events (room_id, origin_server_ts);

-- Index to support DISTINCT ON (event_type, state_key) queries used by build_state_events.
CREATE INDEX events_room_state_idx ON events (room_id, event_type, state_key, origin_server_ts DESC)
    WHERE state_key IS NOT NULL;

-- Thread-relation expression index (was CONCURRENTLY in migration 42, but plain is safe here
-- because this is a fresh database with no rows — no lock contention possible).
CREATE INDEX events_relates_to_event_id_idx
    ON events ((content->'m.relates_to'->>'event_id'))
    WHERE content ? 'm.relates_to';

-- GIN index for full-text search.
CREATE INDEX events_search_vector_gin_idx
    ON events USING GIN (search_vector);

-- ─── sync_tokens ─────────────────────────────────────────────────────────────
-- Final schema from migration 41: composite PK (user_id, device_id).
-- NOT created with old PK then altered — this is the final state directly.
-- user_id references users(user_id) — FK present in original migration 000011
-- and retained in the composite-PK form (migration 000041 kept the FK).
CREATE TABLE sync_tokens (
    user_id       TEXT    NOT NULL REFERENCES users(user_id),
    since_token   TEXT    NOT NULL,
    last_event_id TEXT,
    updated_at    BIGINT  NOT NULL,
    device_id     TEXT    NOT NULL DEFAULT '',
    PRIMARY KEY (user_id, device_id)
);

