-- ─── audit_log ───────────────────────────────────────────────────────────────
-- Append-only compliance event log (Story 5.1).
--
-- In the single-role model (nebu_app = table owner), database-enforced immutability
-- requires FORCE ROW LEVEL SECURITY, which is intentionally omitted here because
-- nebu_app must also be able to call audit_log_purge() for retention cleanup.
-- The no_delete and no_update policies block accidental ORM-layer deletes.
-- Append-only integrity in production is enforced at the application layer (the
-- gateway never issues DELETE or UPDATE on audit_log outside of audit_log_purge()).
-- Dual-role deployments (nebu_migrate as function owner with BYPASSRLS) provide
-- stronger guarantees.
CREATE TABLE audit_log (
    id            BIGSERIAL    PRIMARY KEY,
    event_time    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    actor_user_id TEXT         NOT NULL,
    action        TEXT         NOT NULL,
    target_type   TEXT,
    target_id     TEXT,
    metadata      JSONB,
    outcome       TEXT         NOT NULL,
    error_detail  TEXT
);

ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;
-- Note: FORCE ROW LEVEL SECURITY is intentionally absent — see comment above.

CREATE POLICY audit_log_insert_allow ON audit_log FOR INSERT WITH CHECK (true);
CREATE POLICY audit_log_select_allow ON audit_log FOR SELECT USING (true);
-- These policies block accidental ORM-layer updates and deletes. In single-role
-- mode nebu_app as table owner bypasses RLS (no FORCE RLS), so direct DELETE/UPDATE
-- via the app role will still succeed if issued deliberately. Defense-in-depth for
-- other roles (dual-role deployments, psql sessions with a non-owner role).
CREATE POLICY audit_log_no_update ON audit_log FOR UPDATE USING (false);
CREATE POLICY audit_log_no_delete ON audit_log FOR DELETE USING (false);

-- Defense-in-depth: revoke UPDATE/DELETE at the privilege level for non-owner sessions.
-- In single-role mode where nebu_app IS the table owner this REVOKE is a no-op
-- (owners cannot lose implicit owner privileges). It is meaningful in dual-role
-- deployments where nebu_app connects as a non-owner runtime role.
REVOKE UPDATE, DELETE ON audit_log FROM nebu_app;

-- audit_log_purge: SECURITY DEFINER function for retention cleanup.
-- SECURITY DEFINER is retained for dual-role compatibility (when nebu_migrate is the
-- function owner, elevation bypasses FORCE RLS). In single-role deployments,
-- SECURITY DEFINER is a no-op (caller == owner); purge works because the table owner
-- implicitly bypasses RLS policies without FORCE.
-- Security hardening: SET search_path pinned, EXECUTE restricted to nebu_app only.
CREATE OR REPLACE FUNCTION audit_log_purge(retention_days INT)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    deleted_count BIGINT;
BEGIN
    IF retention_days IS NULL OR retention_days < 1 OR retention_days > 36500 THEN
        RAISE EXCEPTION 'audit_log_purge: retention_days must be between 1 and 36500 (got %)', retention_days
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    DELETE FROM audit_log
    WHERE event_time < NOW() - make_interval(days => retention_days);
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

-- Lock down EXECUTE: PUBLIC must not call a SECURITY DEFINER function.
REVOKE ALL ON FUNCTION audit_log_purge(INT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION audit_log_purge(INT) TO nebu_app;

-- audit_log BEFORE INSERT trigger: forces event_time to NOW() to prevent backdating.
CREATE OR REPLACE FUNCTION audit_log_event_time_force()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  NEW.event_time := NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_log_event_time_force_trigger ON audit_log;
CREATE TRIGGER audit_log_event_time_force_trigger
  BEFORE INSERT ON audit_log
  FOR EACH ROW
  EXECUTE FUNCTION audit_log_event_time_force();

