    FOR INSERT WITH CHECK (true);
CREATE POLICY compliance_sessions_select ON compliance_sessions
    FOR SELECT USING (true);
CREATE POLICY compliance_sessions_update ON compliance_sessions
    FOR UPDATE USING (true);
