);

-- Seed with the system default row.
INSERT INTO room_defaults (default_max_members, default_visibility, set_at)
VALUES (0, 'private', 0);

-- ─── forgotten_rooms ─────────────────────────────────────────────────────────
CREATE TABLE forgotten_rooms (
    -- ON DELETE CASCADE: orphan forgotten_rooms rows are meaningless without the user.
    -- Other user-scoped tables rely on the explicit GDPR deletion handler (GdprDeleteHandler)
    -- and use NO ACTION by design — forgotten_rooms is a lightweight preference store with
    -- no compliance implications, so cascade deletion is safe and desirable here.
    user_id         TEXT    NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    room_id         TEXT    NOT NULL,
    forgotten_at_ms BIGINT  NOT NULL DEFAULT (EXTRACT(EPOCH FROM now()) * 1000)::BIGINT,
    PRIMARY KEY (user_id, room_id)
);

-- ─── events search vector trigger ────────────────────────────────────────────
-- NOTE: trigger function defined here (after the events table and all columns exist).
-- Extracts body from JSONB content for full-text search.
CREATE OR REPLACE FUNCTION events_search_vector_update()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog, public
AS $$
BEGIN
  NEW.search_vector := to_tsvector('pg_catalog.simple',
    coalesce(NEW.content->>'body', ''));
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS events_search_vector_trigger ON events;
CREATE TRIGGER events_search_vector_trigger
  BEFORE INSERT OR UPDATE OF content ON events
  FOR EACH ROW
  EXECUTE FUNCTION events_search_vector_update();

